<?php

/**
 * سرورِ کوچکِ «هر کدِ وضعیتی که بخواهی» — فقط برای تستِ ابزارِ سنجشِ بار (R66).
 *
 * ⚠️ چرا لازم شد: محافظِ اولِ دسته‌بندیِ ۴۲۹ **ساختاری** بود و سه رشته را در
 * سورس می‌سنجید. خرابکاریِ «۴۲۹ را موفق بشمار» از کنارش رد شد، چون آن سه
 * رشته دست‌نخورده مانده بودند و هیچ‌کدام سطلِ `ok` را نگاه نمی‌کردند.
 *
 * تنها راهِ محکمش این است که ابزار واقعاً پاسخِ ۴۲۹ بگیرد و شمارشش سنجیده
 * شود. این فایل با `php -S` بالا می‌آید و هیچ ربطی به برنامه ندارد.
 */
declare(strict_types=1);

$code = (int) ($_GET['code'] ?? 200);

if ($code < 100 || $code > 599) {
    $code = 200;
}

http_response_code($code);
header('Content-Type: application/json');

echo json_encode(['code' => $code]);
